-- Судится открытая версия (и закрытые): задачи и требования следующей и поздних
-- версий её не держат (решение владельца 2026-10-07). Без открытой версии — весь набор.
WITH t AS (SELECT p.id, p.entity_name FROM project_plan_tasks p WHERE p.project_id = $1 AND p.kind = 'dev' AND NOT EXISTS (SELECT 1 FROM task_scope sc WHERE sc.project_id = p.project_id AND sc.task_id = p.id AND sc.scope IN ('next','later'))), need(title) AS (VALUES ('Что делать'),('Признак готовности'),('Чем доказывается'),('Что меняется в дереве')) SELECT t.id || ' — нет раздела «' || need.title || '»' AS detail FROM t CROSS JOIN need WHERE NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = 'task' AND s.entity_name = t.entity_name AND s.title = need.title) UNION ALL SELECT t.id || ' — нет ни «Где обычно ошибаются», ни «Что считается провалом»' FROM t WHERE NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = 'task' AND s.entity_name = t.entity_name AND s.title IN ('Где обычно ошибаются','Что считается провалом')) ORDER BY 1
